// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: One-URL pipeline: fetch, convert, validate, store once, index
// Flo: canonical URL > cached etag > own GET with deadline > pageSave: 304 touch or 2xx convert to UTF-8, validate, save by hash, upsert index + record + log in one transaction
// I/O: URL + Conf + open Db + data dir (caller) > Outc (status word, code, hash); pageSave also takes vendor results (Got)
// ===================================================================
const std = @import("std"); const revi = @import("ru-revi-sche.zig"); const outb = @import("sy-clou-outb.zig"); const vali = @import("sc-reco-vali.zig"); const stru = @import("pa-stru-data.zig"); const html = @import("pa-html-text.zig"); const pdft = @import("pa-pdfz-text.zig"); const ocrz = @import("nt-ocrz-exte.zig"); const urln = @import("ut-urlz-norm.zig"); const fetc = @import("nt-fetc-owns.zig"); const tmfx = @import("nt-fetc-time.zig"); const chrs = @import("pa-char-dete.zig"); const file = @import("st-stor-file.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .vers = "scra/0.1.0", .nxtm = 86400000, .rawd = "raw" };
pub const Outc = struct { urlz: []const u8, code: u16, stat: []const u8, hexz: []const u8, size: usize, kind: []const u8 = "", retr: u32 = 0, tier: i64 = 1, vend: []const u8 = "", cred: u32 = 0, micr: u64 = 0 };
pub const Gotz = struct { code: u16, ctyp: []const u8, body: []const u8, etag: []const u8 = "", lmod: []const u8 = "", retr: u32 = 0, tier: i64 = 1, vend: []const u8 = "", cred: i64 = 0, micr: i64 = 0 };
fn recoMake(aren: std.mem.Allocator, utf8: []const u8, pref: []const []const u8) !inde.Reco { const blks = try stru.blokFind(aren, utf8); for (pref) |kind| { const want: ?stru.Kind = if (std.mem.eql(u8, kind, "ldjs")) .ldjs else if (std.mem.eql(u8, kind, "next")) .next else null; if (want) |wnkd| { for (blks) |blkz| { if (blkz.kind == wnkd and (std.json.validate(aren, blkz.json) catch false)) return .{ .hexz = "", .kind = if (wnkd == .ldjs) "ldjs" else "next", .body = blkz.json }; } } else if (std.mem.eql(u8, kind, "text")) break; } const titl = (try html.htmlTitl(aren, utf8)) orelse ""; const text = try html.htmlText(aren, utf8); return .{ .hexz = "", .kind = "text", .body = try std.fmt.allocPrint(aren, "{s}\n{s}", .{ titl, text }) }; }
pub fn optsMake(aren: std.mem.Allocator, conf: cfgz.Conf, priv: bool) !fetc.Opts { const uagt = if (conf.uagt_cont_mail.len > 0) try std.fmt.allocPrint(aren, "{s} (+{s})", .{ CF.vers, conf.uagt_cont_mail }) else CF.vers; return .{ .time_mill = conf.fetc_time_seco * 1000, .body_maxz = conf.fetc_body_maxz, .redi_maxz = conf.fetc_redi_maxz, .uagt = uagt, .priv_allo = priv, .pdfz_maxz = conf.pdfz_size_maxz }; }
pub fn nowzMill(iozz: std.Io) i64 { return @intCast(std.Io.Clock.real.now(iozz).toMilliseconds()); }
fn logzOnez(dbzz: *sqli.Dbzz, urlz: []const u8, got2: Gotz, note: []const u8, timz: i64) !void { try inde.logzAddz(dbzz, .{ .urlz = urlz, .code = got2.code, .tier = got2.tier, .vend = got2.vend, .cred = got2.cred, .micr = got2.micr, .robo = "none", .timz = timz, .note = note }); }
pub fn pageFetc(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Dbzz, dirz: []const u8, urlz: []const u8, priv: bool) !Outc { const norm = try urln.urlzNorm(aren, urlz); const prev = try inde.pageGetz(dbzz, aren, norm); const cond: fetc.Cond = if (prev) |row2| .{ .etag = row2.etag, .lmod = row2.lmod } else .{}; const timz = nowzMill(iozz); var resp = tmfx.fetcTime(gpaz, iozz, urlz, try optsMake(aren, conf, priv), cond) catch |err3| { try logzOnez(dbzz, norm, .{ .code = 0, .ctyp = "", .body = "" }, @errorName(err3), timz); return err3; }; defer resp.free(gpaz); return pageSave(aren, iozz, conf, dbzz, dirz, norm, prev, .{ .code = resp.code, .ctyp = resp.ctyp, .body = resp.body, .etag = resp.etag, .lmod = resp.lmod, .retr = resp.retr }); }
pub fn pageSave(aren: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Dbzz, dirz: []const u8, norm: []const u8, prev: ?inde.Rowz, got2: Gotz) !Outc { const timz = nowzMill(iozz);
if (got2.code == 304 and prev != null) { const row2 = prev.?; var updz = row2; updz.fetc = timz; updz.intv = revi.reviNext(row2, false, conf); updz.next = timz + updz.intv; try dbzz.exec("BEGIN IMMEDIATE;"); errdefer dbzz.exec("ROLLBACK;") catch {}; try inde.pageSetz(dbzz, norm, updz); try logzOnez(dbzz, norm, got2, "not modified", timz); try dbzz.exec("COMMIT;"); return .{ .urlz = norm, .code = 304, .stat = "notm", .hexz = row2.hexz, .size = 0 }; }
if (got2.code < 200 or got2.code >= 300) { try logzOnez(dbzz, norm, got2, "http status, not stored", timz); return .{ .urlz = norm, .code = got2.code, .stat = "http", .hexz = "", .size = 0, .retr = got2.retr }; }
const ispd = std.ascii.findIgnoreCase(got2.ctyp, "application/pdf") != null; var pdfr: pdft.Rslt = undefined; if (ispd) { pdfr = pdft.pdfzText(std.heap.page_allocator, aren, got2.body) catch |err3| { try logzOnez(dbzz, norm, got2, try std.fmt.allocPrint(aren, "rejected pdf: {s}", .{@errorName(err3)}), timz); return .{ .urlz = norm, .code = got2.code, .stat = if (err3 == error.Encrypted) "encr" else "badp", .hexz = "", .size = 0 }; }; if (pdfr.ocrz and conf.ocrz_enab and conf.ocrz_path_exec.len > 0) { if (ocrz.ocrzRunz(aren, iozz, conf.ocrz_path_exec, got2.body, dirz)) |otxz| { if (otxz.len > 0) pdfr = .{ .text = otxz, .pag2 = pdfr.pag2, .ocrz = false }; } else |_| {} } } const utf8 = if (ispd) got2.body else try chrs.utf8Conv(aren, chrs.charFind(got2.ctyp, got2.body), got2.body); const isnd = std.ascii.findIgnoreCase(got2.ctyp, "ndjson") != null; const verd = if (ispd or isnd) (if (utf8.len > 0) vali.Verd.okay else vali.Verd.empt) else try vali.pageVali(aren, got2.ctyp, utf8); if (verd != .okay) { try logzOnez(dbzz, norm, got2, try std.fmt.allocPrint(aren, "rejected: {s}", .{@tagName(verd)}), timz); return .{ .urlz = norm, .code = got2.code, .stat = @tagName(verd), .hexz = "", .size = 0 }; } const rawd = try std.fs.path.join(aren, &.{ dirz, CF.rawd }); const sav2 = try file.fileSave(aren, iozz, rawd, utf8); const same = prev != null and std.mem.eql(u8, prev.?.hexz, &sav2.hexz); const hexz = try aren.dupe(u8, &sav2.hexz); const intv = revi.reviNext(prev, prev != null and !same, conf);
try dbzz.exec("BEGIN IMMEDIATE;"); errdefer dbzz.exec("ROLLBACK;") catch {}; try inde.pageSetz(dbzz, norm, .{ .hexz = hexz, .etag = got2.etag, .lmod = got2.lmod, .code = got2.code, .tier = got2.tier, .vend = got2.vend, .fetc = timz, .next = timz + intv, .intv = intv }); try logzOnez(dbzz, norm, got2, if (same) "same content" else "stored", timz); var reco: inde.Reco = if (isnd) .{ .hexz = "", .kind = "strm", .body = utf8 } else if (ispd) .{ .hexz = "", .kind = if (pdfr.ocrz) "pdfo" else "pdft", .body = pdfr.text } else if (std.ascii.findIgnoreCase(got2.ctyp, "json") != null) .{ .hexz = "", .kind = "json", .body = utf8 } else try recoMake(aren, utf8, conf.extr_pref_list); reco.hexz = hexz; try inde.recoSetz(dbzz, norm, reco, timz); if (!same) { try outb.outbAddz(dbzz, "file", hexz, timz, false); try outb.outbAddz(dbzz, "rec", norm, timz, true); } try dbzz.exec("COMMIT;");
return .{ .urlz = norm, .code = got2.code, .stat = if (same) "same" else "new", .hexz = hexz, .size = utf8.len, .kind = reco.kind }; }
